import{_ as a,o as n,c as r,ae as t}from"./chunks/framework.Cqu5Y2mC.js";const g=JSON.parse('{"title":"Protokoll Sitzung 07","description":"","frontmatter":{},"headers":[],"relativePath":"05-Gemeinsam/2026-05-08-Protokoll.md","filePath":"05-Gemeinsam/2026-05-08-Protokoll.md"}'),l={name:"05-Gemeinsam/2026-05-08-Protokoll.md"};function i(o,e,s,u,h,d){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="protokoll-sitzung-07" tabindex="-1">Protokoll Sitzung 07 <a class="header-anchor" href="#protokoll-sitzung-07" aria-label="Permalink to &quot;Protokoll Sitzung 07&quot;">​</a></h1><p><strong>Datum:</strong> <em><strong>2026-05-08</strong></em><br><strong>Sitzung:</strong> <em><strong>07</strong></em><br><strong>Protokollführer:</strong> <em><strong>Sofia Jäger</strong></em></p><p><strong>Teilnehmer:</strong><br><strong>Lehrer:</strong> <em><strong>Stefan Martin, Karl Laber</strong></em><br><strong>Schüler:</strong><br><em><strong>01-Betrieb: Huzaifa, Irakli, Marius</strong></em><br><em><strong>02-Hardware: Eray, Lukas, Marlon</strong></em><br><em><strong>03-Software: Felix, Jannick, Theodor</strong></em><br><em><strong>04-Projektleitung: Daniel, Sofia</strong></em></p><hr><h2 id="aktueller-stand-ruckblick-seit-der-letzten-sitzung" tabindex="-1">Aktueller Stand/ Rückblick seit der letzten Sitzung: <a class="header-anchor" href="#aktueller-stand-ruckblick-seit-der-letzten-sitzung" aria-label="Permalink to &quot;Aktueller Stand/ Rückblick seit der letzten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>Sie haben die Daten der Sensoren als Hexadezimal Code erhalten.</li><li>Sie haben diese Daten anhand von Code (von Felix/ Softwareteam) dekodiert.</li></ul><h3 id="_2-hardware" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>Der Sensor sendet Daten.</li><li>Sie haben den ersten Sensor montiert.</li><li>Sie haben die ungefähre Reichweite der Antenne getestet.</li><li>Sie haben eine neue Halterung an einem neuen Mülleimer montiert.</li><li>Sie haben den Sensor getestet (ob der Abstand, den er ausgibt, stimmt).</li></ul><h3 id="_3-software" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Problembehebung der Datenversendung.</li><li>Empfangen einer noch nicht angepassten Datenbank.</li></ul><h3 id="_4-projektleitung" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>Abgesprochen, wer alles zur Abschlussveranstaltung eingeladen werden soll (Siehe Konzept_Abschlussveranstaltung).</li><li>Ablauf der Veranstaltung durchgesprochen und geplant (Siehe Konzept_Abschlussveranstaltung).</li><li>Nuudel-Umfrage zur Terminfindung versendet.</li><li>Frau Bieler darum gebeten, den Termin mit Rathausangestellten abzuklären.</li><li>Frau Bieler bekannt gegeben, dass wir uns gerne persönlich mit ihr treffen würden (ggf. im Rathaus), um den Ablauf der Abschlussveranstaltung absprechen zu können.</li></ul><h3 id="_5-allgemein" tabindex="-1">5. Allgemein: <a class="header-anchor" href="#_5-allgemein" aria-label="Permalink to &quot;5. Allgemein:&quot;">​</a></h3><ul><li>Herr Laber hat Herrn Bucher angerufen um abzusprechen, ob wir eine Antenne und Basisstation bekommen können.</li></ul><hr><h2 id="ziele-bis-zur-nachsten-sitzung" tabindex="-1">Ziele bis zur nächsten Sitzung: <a class="header-anchor" href="#ziele-bis-zur-nachsten-sitzung" aria-label="Permalink to &quot;Ziele bis zur nächsten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb-1" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb-1" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>Noch unbekannt.</li></ul><h3 id="_2-hardware-1" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware-1" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>Warten auf die neue Antenne und das Gateway.</li><li>Wenn die Antenne und das Gateway da sind: Neue Mülleimer bestücken, um neue Messdaten zu erhalten.</li></ul><h3 id="_3-software-1" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software-1" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Problembehebung und Anpassung der Datenbank.</li></ul><h3 id="_4-projektleitung-1" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung-1" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>Warten auf Rückmeldung per Umfrage.</li><li>Warten auf Antwort von Frau Bieler bezüglich Terminabsprache mit Rathaus.</li><li>Warten auf Antwort von Frau Bielder bezüglich Treffen, um Ablauf der Abschlussveranstaltung zu besprechen.</li><li>Protokoll 08.05.2026 schreiben und hochladen.</li><li>Lehrer nehmen Konktakt mit Herrn Gantner (Fachlehrer GMT) auf, um ihn um Hilfe bezüglich Plakate, Flyer, Design etc. zu bitten.</li></ul><h3 id="_5-allgemein-1" tabindex="-1">5. Allgemein: <a class="header-anchor" href="#_5-allgemein-1" aria-label="Permalink to &quot;5. Allgemein:&quot;">​</a></h3><ul><li>Neue Antenne und Basisstation bekommen.</li></ul>',27)])])}const m=a(l,[["render",i]]);export{g as __pageData,m as default};
